export const colorectalCoreTerms: TermInput[] = [
  tm({ id: "adenoma-carcinoma-sequence", name: "Adenoma-carcinoma sequence", category: "Cancer biology", wikipedia: W("Colorectal_cancer"),
    aka: ["adenoma to carcinoma sequence", "Vogelstein model", "chromosomal instability pathway", "conventional pathway", "APC-KRAS-TP53 sequence"],
    tldr: "The adenoma-carcinoma sequence is the step-by-step route by which a normal bowel lining becomes a polyp and the polyp becomes a cancer, as genetic faults pile up over years. It is why removing polyps prevents cancer, and it was the first human cancer to be mapped this way.",
    summary: "The sequence was mapped in 172 colorectal specimens representing every stage from small adenoma to carcinoma. RAS mutations were present in 58 percent of adenomas larger than 1 cm but in only 9 percent of adenomas under 1 cm; the chromosome 5 region carrying the polyposis gene was lost in 29 to 35 percent of adenomas and carcinomas from patients without polyposis; a region of chromosome 18 was deleted in 73 percent of carcinomas, 47 percent of advanced adenomas and 11 to 13 percent of early adenomas; and chromosome 17p was usually lost only in carcinomas (75 percent). The four alterations accumulated in step with clinical progression, which is the observation the model rests on (Vogelstein 1988). The 1990 synthesis generalised it: cancer arises from the mutational activation of oncogenes coupled with the inactivation of several tumour suppressor genes, at least four or five alterations are needed, and it is the accumulation rather than the order that determines the biology, so tumours with the same set of changes but acquired in different orders behave alike (Fearon and Vogelstein 1990).\n\nWhat it means in practice. First, time: the years an adenoma takes to become a carcinoma are the window screening works in. Second, prevention: if the polyp is the obligate precursor, removing it should prevent the cancer, and the National Polyp Study showed exactly that, with 76 to 90 percent fewer cancers than expected in 1,418 patients whose adenomas were removed and 53 percent lower colorectal cancer mortality at a median of 15.8 years (Winawer 1993; Zauber 2012). Third, limits: this is not the only route. About 30 percent of colorectal carcinomas arise through the serrated pathway instead, from flatter lesions with promoter methylation and BRAF or KRAS mutation, and those are the lesions screening misses most often (Bettington 2013). The sequence also underlies familial adenomatous polyposis, where the gatekeeper gene APC is lost in the germline and the field of adenomas is enormous.",
    cancers: ["colorectal", "colon-cancer", "rectal-cancer", "fap-associated-colorectal-cancer", "colorectal-adenoma-like-adenocarcinoma"],
    terms: ["serrated-pathway", "colorectal-polyp-types", "colonoscopy", "colonoscopy-surveillance-intervals"],
    targets: ["kras", "tp53"], pathways: ["wnt", "ras-mapk"], technologies: ["colorectal-screening"],
    links: [SRC.vogelstein1988, SRC.fearon1990, SRC.winawer1993, SRC.zauber2012, SRC.bettington2013] }),

  tm({ id: "serrated-pathway", name: "Serrated pathway", category: "Cancer biology", wikipedia: W("Sessile_serrated_lesion"),
    aka: ["serrated neoplasia pathway", "sessile serrated lesion pathway", "serrated polyp pathway", "CpG island methylator phenotype pathway"],
    tldr: "The serrated pathway is the second route to bowel cancer, running not through the familiar mushroom-shaped polyp but through flat, pale, saw-toothed lesions that are easy to miss at colonoscopy and rarely bleed. It accounts for about three in ten bowel cancers and for most of the ones whose DNA proofreading has broken down by accident rather than by inheritance.",
    summary: "About 30 percent of colorectal carcinomas develop through a serrated route, named for the saw-tooth pattern of the crypts in the precursor polyps. The molecular signature is methylation of CpG islands, of low or high degree, with an activating mutation in BRAF or KRAS; microsatellite instability is often present, which allows serrated pathway cancers to be grouped as BRAF-mutant and highly methylated with either unstable or stable microsatellites, or KRAS-mutant with low methylation and stable microsatellites (Bettington 2013). The precursors are the microvesicular hyperplastic polyp, the sessile serrated lesion (proximal, with distorted crypt architecture and BRAF mutation) and the traditional serrated adenoma (left-sided, tubulovillous, eosinophilic, more often KRAS-mutant). Cytological dysplasia in a sessile serrated lesion marks a sharply higher risk of progression. Serrated adenocarcinoma, a separate World Health Organization subtype with well-differentiated, mucinous or trabecular patterns, is the carcinoma this route produces and has its own record.\n\nWhy it matters for screening and surveillance. Serrated lesions are flat, pale and often covered by a mucus cap, so they are harder to see and harder to remove completely than adenomas; they bleed rarely, so faecal tests detect few of them; and missed serrated polyps are a recognised contributor to preventable colorectal cancers. A detection-rate benchmark for sessile serrated polyps and serrated-specific surveillance strategies are the current responses (Expert Rev Gastroenterol Hepatol 2025). Histological separation of a hyperplastic polyp from a sessile serrated lesion remains difficult and is a source of variation between pathologists, which feeds straight through into the surveillance interval a patient is given. The UK surveillance guidelines count a serrated polyp of at least 10 mm, or one containing any grade of dysplasia, as an advanced colorectal polyp (Rutter 2020).",
    cancers: ["colorectal", "colorectal-serrated-adenocarcinoma", "msi-high-colorectal", "braf-v600e-colorectal", "colon-cancer"],
    terms: ["adenoma-carcinoma-sequence", "colorectal-polyp-types", "colonoscopy-surveillance-intervals", "msi", "mlh1-promoter-methylation"],
    targets: ["braf", "kras"], technologies: ["colorectal-screening", "colonoscopy", "histopathology-ihc"],
    links: [SRC.bettington2013, SRC.serrated2025, SRC.rutter2020, SRC.whoGi] }),

  tm({ id: "colorectal-polyp-types", name: "Polyp types in the bowel", category: "Pathology", wikipedia: W("Colorectal_polyp"),
    aka: ["bowel polyp types", "colorectal polyps", "adenoma", "sessile serrated lesion", "hyperplastic polyp", "traditional serrated adenoma", "advanced adenoma", "advanced colorectal polyp"],
    tldr: "A polyp is a growth on the lining of the bowel. Most are harmless, but two families can turn into cancer: adenomas, the classic route, and serrated lesions, the flatter and easier-to-miss route. Which kind you had, how many, how big and whether the cells looked abnormal decide when you are asked back.",
    summary: "Polyps found at colonoscopy fall into groups that behave very differently. Conventional adenomas are dysplastic by definition and are the precursor of the adenoma-carcinoma sequence; they are described as tubular, tubulovillous or villous by architecture and as low or high grade by dysplasia. Serrated polyps divide into hyperplastic polyps (including the microvesicular type), sessile serrated lesions and traditional serrated adenomas, and are the precursors of the serrated pathway. Inflammatory and hamartomatous polyps, including juvenile and Peutz-Jeghers polyps, are separate again.\n\nWhat makes a polyp advanced. The UK guidelines define an advanced colorectal polyp as a serrated polyp of at least 10 mm or containing any grade of dysplasia, or an adenoma of at least 10 mm or containing high-grade dysplasia; the high-risk group after polypectomy is either two or more premalignant polyps including at least one advanced polyp, or five or more premalignant polyps (Rutter 2020). The European guideline draws similar lines: one to four adenomas under 10 mm with low-grade dysplasia, or any serrated polyp under 10 mm without dysplasia, need no surveillance at all, while an adenoma of 10 mm or more, high-grade dysplasia, five or more adenomas, or a serrated polyp of 10 mm or more or with dysplasia earn a colonoscopy at three years (ESGE 2020).\n\nWhat the numbers mean for risk. About 1 percent of people whose adenomas were 20 mm or more, or contained high-grade dysplasia, develop bowel cancer within about four years of removal; the risk of advanced bowel cancer is 80 percent higher in people with low-risk polyps at first colonoscopy than in people with none (Cancer Research UK). Risk factors act on polyps as they act on cancer: adenoma risk is 47 percent higher in obesity and about twice as high in current smokers, and serrated polyp risk is more than twice as high in current smokers and 23 percent higher with the highest red meat intake.",
    cancers: ["colorectal", "colon-cancer", "rectal-cancer", "fap-associated-colorectal-cancer"],
    terms: ["adenoma-carcinoma-sequence", "serrated-pathway", "colonoscopy", "colonoscopy-surveillance-intervals", "dysplasia", "tumour-grade"],
    technologies: ["colonoscopy", "colorectal-screening", "histopathology-ihc"],
    links: [SRC.rutter2020, SRC.esge2020, SRC.crukRisk, SRC.bettington2013] }),

  tm({ id: "bowel-cancer-screening-uk", name: "NHS bowel cancer screening programme", category: "Epidemiology & prevention", wikipedia: W("Colorectal_cancer_screening"),
    aka: ["NHS bowel screening", "bowel cancer screening programme", "BCSP", "bowel screening kit", "FIT kit", "home test kit for bowel cancer"],
    tldr: "The NHS posts a home test for hidden blood in the poo to everyone aged 50 to 74 in England every two years. Most people are told no further tests are needed; if blood is found they are offered a colonoscopy. It is the only NHS cancer screening programme that can prevent the cancer as well as find it early, because the colonoscopy removes the polyps.",
    summary: "What is offered. England invites everyone aged 50 to 74 registered with a GP for a faecal immunochemical test every two years. The programme was extended down from 60, so depending on when a person turned 50 the first kit arrives at 50, 52 or 54. An invitation letter and information leaflet come first, the kit about a week later, and results about two weeks after the laboratory receives the sample. People aged 75 and over can request a kit every two years on the free helpline (0800 707 6060). An abnormal result leads to an appointment with a specialist screening practitioner and usually to a colonoscopy; blood in the stool is more often an anal fissure or a polyp than a cancer. Screening does not stop a person getting bowel cancer, and symptoms after a normal result still need a GP (NHS; GOV.UK).\n\nThe threshold. The faecal immunochemical test measures haemoglobin in micrograms per gram of faeces, and the programme chooses a cut-off that its colonoscopy capacity can absorb. England screens at 120 micrograms per gram. Modelling from the English pilot of 27,238 people aged 59 to 75 estimated that two-yearly screening at that threshold generates 16,092 colonoscopies per 100,000 screened, prevents 186 cancers, and detects 1,142 cancers, 7,086 adenomas and 4,259 advanced adenomas (Br J Cancer 2022). The same test used in primary care for people with symptoms refers at 10 micrograms per gram, twelve times lower, because the pre-test probability there is far higher (NICE NG12 1.3.2).\n\nHow well it works and who takes it up. The programme standards set an acceptable uptake of 62 percent and an achievable level of 73 to 76 percent for ages 60 to 74, with levels for the newly invited 50 to 59 group not yet set. In England in 2019, 12 percent of bowel cancers were diagnosed through screening, against 38 percent through an urgent suspected cancer referral and 22 percent after an emergency presentation (Cancer Research UK). The randomised evidence behind faecal testing and endoscopy is in the colorectal screening technology record and the glossary term for the faecal immunochemical test.",
    cancers: ["colorectal", "colon-cancer", "rectal-cancer"],
    terms: ["fit-test", "colonoscopy", "emergency-presentation", "stage-shift", "colonoscopy-surveillance-intervals"],
    technologies: ["colorectal-screening", "colonoscopy"],
    links: [SRC.nhsScreening, SRC.govBcsp, SRC.fitPilot2022, SRC.ng12, SRC.crukMain] }),

  tm({ id: "colonoscopy-surveillance-intervals", name: "Surveillance intervals after polypectomy", category: "Procedures", wikipedia: W("Colonoscopy"),
    aka: ["post-polypectomy surveillance", "surveillance colonoscopy interval", "when is my next colonoscopy", "post-colorectal cancer resection surveillance"],
    tldr: "After polyps are removed, the date of your next colonoscopy is set by what was found, not by habit. In the UK, most people go back to routine screening; only those with several premalignant polyps or one advanced one are brought back at three years, and people who have had bowel cancer removed have a clearance test at one year.",
    summary: "The UK rules. The British Society of Gastroenterology, the Association of Coloproctology of Great Britain and Ireland and Public Health England set out the first surveillance guidelines to take the national screening programme into account, and the first to cover serrated as well as adenomatous polyps. The high-risk criteria after polypectomy are either two or more premalignant polyps including at least one advanced colorectal polyp (a serrated polyp of at least 10 mm or containing any dysplasia, or an adenoma of at least 10 mm or containing high-grade dysplasia), or five or more premalignant polyps. That group has a one-off surveillance colonoscopy at three years. After resection of a colorectal cancer, the pattern is a clearance colonoscopy at one year and a surveillance colonoscopy three years after that (Rutter 2020).\n\nThe European rules, for comparison. Patients with one to four adenomas under 10 mm with low-grade dysplasia, whatever the villous content, or any serrated polyp under 10 mm without dysplasia, need no endoscopic surveillance and return to screening; where organised screening is not available, a colonoscopy at ten years is recommended. Surveillance at three years follows complete removal of an adenoma of 10 mm or more, an adenoma with high-grade dysplasia, five or more adenomas, or a serrated polyp of 10 mm or more or with dysplasia. Piecemeal removal of a polyp of 20 mm or more is checked at three to six months and again at twelve. If the first surveillance test is clear, a second is suggested at five years, after which the patient returns to screening (ESGE 2020).\n\nWhy the interval is the treatment. A surveillance colonoscopy is a scarce resource: every interval shortened for one patient is a colonoscopy not available for a screening positive or a symptomatic referral, which is also why the screening threshold sits where it does. NICE NG151 (1.6.1) adds the separate follow-up after curative surgery for non-metastatic disease: carcinoembryonic antigen and computed tomography of the chest, abdomen and pelvis for the first three years.",
    cancers: ["colorectal", "colon-cancer", "rectal-cancer", "lynch-associated-colorectal-cancer", "fap-associated-colorectal-cancer"],
    terms: ["colorectal-polyp-types", "colonoscopy", "adenoma-carcinoma-sequence", "serrated-pathway", "bowel-cancer-screening-uk"],
    technologies: ["colonoscopy", "colorectal-screening", "cea-surveillance-colorectal"],
    links: [SRC.rutter2020, SRC.esge2020, SRC.ng151] }),

  tm({ id: "watch-and-wait-rectal-cancer", name: "Watch and wait after chemoradiotherapy for rectal cancer", category: "Treatment jargon", wikipedia: W("Watchful_waiting"),
    aka: ["watch and wait rectal cancer", "non-operative management of rectal cancer", "deferral of surgery", "organ preservation rectal cancer", "watch-and-wait"],
    tldr: "In some people the rectal tumour disappears completely after chemotherapy and radiotherapy. Watch and wait means keeping the rectum and checking it closely instead of removing it, and operating only if the tumour comes back. About a quarter of regrowths happen, almost all within two years, and almost all can still be operated on.",
    summary: "What it is. After chemoradiotherapy, a minority of rectal tumours leave no trace on digital examination, endoscopy (a flat white scar) or magnetic resonance imaging. Rather than proceed to total mesorectal excision, with its stoma risk and its effect on bowel, urinary and sexual function, the team can keep the rectum and watch it intensively. The finding that justifies it is the clinical complete response, which has its own glossary term.\n\nThe evidence. The International Watch and Wait Database pooled 1,009 patients from 47 institutions in 15 countries and analysed the 880 with a clinical complete response. The two-year cumulative incidence of local regrowth was 25.2 percent; 88 percent of regrowths appeared in the first two years and 97 percent were in the bowel wall, where endoscopy can find them and surgery can still remove them. Distant metastases occurred in 8 percent. Five-year overall survival was 85 percent and five-year disease-specific survival 94 percent (van der Valk 2018). The OPRA trial randomised 324 patients with stage II or III rectal cancer to induction chemotherapy then chemoradiotherapy, or chemoradiotherapy then consolidation chemotherapy, offering watch and wait to those with a complete or near-complete response. At three years, disease-free survival was 76 percent in both arms and rectum-free survival 41 and 53 percent; at a median of 5.1 years, five-year disease-free survival was 71 and 69 percent and rectum-free survival 39 and 54 percent. Of the 81 patients who had a regrowth, 94 percent occurred within two years and 99 percent within three, and disease-free survival was the same (64 percent) whether the rectum was removed after restaging or after a regrowth (Garcia-Aguilar 2022; 2024).\n\nWhat the guidelines say. NICE NG151 (1.3.7) asks clinicians to tell people with a complete clinical and radiological response who wish to defer surgery that there is a risk of recurrence and that no prognostic factor identifies who can safely defer, to encourage entry into a clinical trial, and to make sure the outcome is recorded in a national registry. In mismatch repair-deficient rectal cancer the route to organ preservation is immunotherapy rather than chemoradiotherapy, and the parent record carries those trials.",
    cancers: ["colorectal", "rectal-cancer", "msi-high-colorectal"],
    terms: ["clinical-complete-response", "organ-preservation", "total-mesorectal-excision", "total-neoadjuvant-therapy", "circumferential-resection-margin"],
    technologies: ["mri", "imrt-igrt", "endoscopy"],
    links: [SRC.iwwd2018, SRC.opra2022, SRC.opra2024, SRC.ng151] }),

  tm({ id: "circumferential-resection-margin", name: "Circumferential resection margin (rectal cancer)", category: "Pathology", wikipedia: W("Total_mesorectal_excision"),
    aka: ["CRM", "circumferential margin", "radial resection margin", "lateral resection margin", "mesorectal fascia", "threatened margin"],
    tldr: "The circumferential resection margin is the side surface of the removed rectum, the plane the surgeon cut along. If cancer cells lie within a millimetre of it, the cancer is much more likely to come back in the pelvis. It is measured on the scan before surgery and on the specimen afterwards, and it is the single reading that most shapes rectal cancer treatment.",
    summary: "Where it came from. In 1986 Quirke sliced 52 whole rectal specimens transversely rather than sampling them: 14 of 52 (27 percent) had tumour spread to the lateral resection margin and 12 of those 14 went on to local pelvic recurrence, with a specificity of 92 percent, sensitivity of 95 percent and positive predictive value of 85 percent. A stage- and grade-matched control series had the same recurrence rate but no lateral spread recorded, because routine sampling had missed it. Local recurrence was reinterpreted as the consequence of lateral spread left behind, not of inherent aggressiveness (Quirke 1986). The surgical answer had already been described: total mesorectal excision, removing the whole mesorectal envelope rather than cutting into it (Heald 1982).\n\nWhat involvement predicts. A review of more than 17,500 patients found that an involved margin predicts local recurrence, distant metastases (hazard ratio 2.8) and shorter survival (hazard ratio 1.7), and that its predictive value for local recurrence is significantly greater after preoperative radiotherapy or chemoradiotherapy than without it (hazard ratio 6.3 against 2.0) (Nagtegaal and Quirke 2008). The conventional definition of involvement is tumour within 1 mm of the margin.\n\nReading it before surgery. High-resolution pelvic magnetic resonance imaging measures the distance from tumour to the mesorectal fascia, the plane that becomes the margin. In the MERCURY study of 408 consecutive patients across 11 European units, 87 percent had a clear margin at pathology; magnetic resonance imaging predicted a clear margin with 92 percent specificity, and of the 349 patients it predicted clear, 327 (94 percent) were clear at surgery (BMJ 2006). MERCURY II extended the approach to low rectal cancers within 6 cm of the anal verge, classifying the relationship of tumour to the surgical plane as safe or unsafe in 279 patients with an overall pathological margin involvement rate of 9.0 percent. A threatened margin on the scan is the usual reason to give radiotherapy or chemoradiotherapy before surgery rather than operating first.",
    cancers: ["colorectal", "rectal-cancer", "colon-cancer", "colorectal-micropapillary-carcinoma"],
    terms: ["total-mesorectal-excision", "resection-margins", "watch-and-wait-rectal-cancer", "total-neoadjuvant-therapy", "tnm-staging"],
    technologies: ["mri", "histopathology-ihc", "imrt-igrt"],
    links: [SRC.quirke1986, SRC.heald1982, SRC.nagtegaalCrm, SRC.mercury2006, SRC.mercury2, SRC.ng151] }),

  tm({ id: "obstructing-colorectal-cancer", name: "Obstruction and T4 disease in bowel cancer", category: "Clinical", wikipedia: W("Bowel_obstruction"),
    aka: ["bowel obstruction from cancer", "obstructing colorectal cancer", "large bowel obstruction", "colonic stent", "bridge to surgery", "T4 colon cancer", "locally advanced colon cancer"],
    tldr: "Sometimes a bowel cancer is found only when it blocks the bowel or has grown through its outer wall into the peritoneum or a neighbouring organ. Both change the plan: a blockage may be relieved with a stent so that surgery can be done calmly a few weeks later, and a tumour that has grown outside the bowel may be given chemotherapy first.",
    summary: "Obstruction. Colorectal cancer often presents with a blockage that needs urgent decompression, and about one in five people with an untreated primary tumour develops obstruction, perforation, bleeding or pain needing surgery (NICE NG151). NICE offers stenting for people being treated with palliative intent (1.3.1) and either stenting or emergency surgery for those in whom cure is still possible (1.3.2). The CReST trial randomised 245 patients from 39 hospitals with left-sided obstruction to a stent followed by elective surgery one to four weeks later, or to surgical decompression. Stenting was attempted in 96.7 percent and relieved obstruction in 82.4 percent. Among the 89 percent treated with curative intent there was no significant difference in 30-day postoperative mortality (3.6 against 5.6 percent) or hospital stay (median 19 against 18 days), but stoma formation fell from 67.9 to 47.5 percent, with no difference in perioperative morbidity, critical care use, quality of life, three-year recurrence or mortality (Hill 2022).\n\nT4 disease. T4a means the tumour has grown through the outer lining of the bowel wall into the peritoneum; T4b means it has grown into a nearby organ (Cancer Research UK). Both carry a higher risk of recurrence, and T4b often needs resection of more than the bowel. NICE NG151 (1.3.16) says to consider preoperative systemic anticancer therapy for cT4 colon cancer, on the strength of the FOxTROT trial, in which patients with radiologically staged T3 to T4, N0 to N2, M0 colon cancer were allocated to six weeks of oxaliplatin and fluoropyrimidine before surgery plus eighteen after, or twenty-four weeks after surgery alone; 96 percent of those allocated to preoperative treatment started it (FOxTROT Collaborative Group 2023). T4 disease, obstruction, fewer than twelve examined nodes and lymphovascular invasion are also the features that make a stage II colon cancer high-risk and bring adjuvant chemotherapy into the discussion; the parent record carries those rows.",
    cancers: ["colorectal", "colon-cancer", "rectal-cancer"],
    terms: ["tnm-staging", "colectomy", "lymphovascular-invasion", "emergency-presentation", "conversion-therapy-colorectal"],
    technologies: ["endoscopy", "ct"],
    links: [SRC.ng151, SRC.crest2022, SRC.foxtrot2023, SRC.crukTnm] }),

  tm({ id: "liver-limited-metastatic-colorectal", name: "Liver-limited metastatic bowel cancer", category: "Clinical", wikipedia: W("Colorectal_cancer"),
    aka: ["colorectal liver metastases", "liver-only metastatic colorectal cancer", "oligometastatic colorectal cancer", "resectable liver metastases", "metastasectomy"],
    tldr: "Bowel cancer that has spread only to the liver, and sometimes only to the lung, is one of the few forms of secondary cancer treated with the aim of cure. If the deposits can be removed or destroyed, with chemotherapy before and after, a substantial minority of people are alive five years later.",
    summary: "Why it is treated differently. The liver is the first place colorectal cancer spreads, through the portal vein, and disease confined to it is not biologically the same as disease scattered through several organs. NICE NG151 asks a multidisciplinary team with expertise in resecting disease at all involved sites to consider resection, either at the same operation as the primary or sequentially (1.5.15), to consider perioperative systemic anticancer therapy when resection is suitable (1.5.16), and to consider chemotherapy with local ablative techniques when resection is not (1.5.17). Selective internal radiation therapy is not offered first line for liver metastases unsuitable for local treatment (1.5.18). Lung metastases suitable for local treatment are handled the same way, with metastasectomy, ablation or stereotactic body radiotherapy after discussion by a team including a thoracic surgeon (1.5.19).\n\nWhat the numbers are. In EORTC 40983, 364 patients with up to four resectable liver metastases were randomised to six cycles of FOLFOX4 before and six after surgery or to surgery alone; three-year progression-free survival rose by 7.3 percentage points in all randomised patients, 8.1 in eligible patients and 9.2 in those who actually had a resection (from 33.2 to 42.4 percent, hazard ratio 0.73), with more reversible postoperative complications after chemotherapy (25 against 16 percent) (Nordlinger 2008). In England, among people whose colorectal liver metastases could be operated on, around 45 percent survived five years or more after the operation, a figure that includes deaths from other causes (Morris 2010, quoted by Cancer Research UK).\n\nWhat it means for a patient. The first question after a liver-only diagnosis is not which chemotherapy but whether a liver surgeon has seen the scan, because operability is a judgement made by a specialist team and can change after treatment. Where the disease is not removable at first, the aim becomes conversion, which has its own term.",
    cancers: ["colorectal", "colon-cancer", "rectal-cancer"],
    terms: ["conversion-therapy-colorectal", "colorectal-peritoneal-metastases", "sidedness", "obstructing-colorectal-cancer"],
    technologies: ["thermal-ablation", "sbrt", "ct", "mri"],
    links: [SRC.ng151, SRC.nordlinger2008, SRC.morris2010, SRC.crukSurvPatient] }),

  tm({ id: "conversion-therapy-colorectal", name: "Conversion therapy in bowel cancer", category: "Treatment jargon", wikipedia: W("Colorectal_cancer"),
    aka: ["conversion chemotherapy", "downsizing chemotherapy", "secondary resectability", "conversion to resectable", "downstaging for liver resection"],
    tldr: "Conversion therapy means giving drugs to shrink secondary tumours that cannot be operated on at first, in the hope that they become small enough to remove. It is a different goal from simply controlling the disease: the treatment is chosen for how hard it shrinks the tumour, and the scans are reviewed by a surgeon every couple of months.",
    summary: "The idea. When colorectal cancer has spread to the liver but is technically unresectable or too numerous to remove, the aim of first-line treatment can be to make surgery possible rather than to hold the disease still. That changes the choice of regimen towards the combinations with the highest response rates, and it changes the follow-up: the scans are reassessed by a surgeon at intervals, not only for progression.\n\nThe evidence. CELIM randomised 111 patients with non-resectable liver metastases (technically unresectable or five or more deposits) to cetuximab with FOLFOX6 or with FOLFIRI. A confirmed partial or complete response occurred in 68 and 57 percent of the two arms, and R0 resection followed in 38 and 30 percent. A blinded retrospective surgical review of the imaging found resectability rose from 32 percent at baseline to 60 percent after chemotherapy. Response was strongly dependent on genotype: 70 percent of patients with KRAS wild-type tumours responded against 41 percent of those with KRAS-mutant tumours (Folprecht 2010). That genotype dependence is why RAS and BRAF testing comes before the regimen is chosen (NICE NG151 1.4.1), and why sidedness enters the decision as well.\n\nWhat the term does not mean. Conversion is not the same as perioperative chemotherapy for metastases that were already removable, which is the EORTC 40983 question, and it is not the same as a clinical complete response on imaging: disappearing metastases on the scan frequently harbour residual disease, so the surgeon still resects where the deposit was. The parent record carries the first-line regimens and their biomarker rules.",
    cancers: ["colorectal", "colon-cancer", "rectal-cancer"],
    terms: ["liver-limited-metastatic-colorectal", "sidedness", "obstructing-colorectal-cancer", "neoadjuvant-adjuvant"],
    targets: ["kras", "egfr", "braf"],
    links: [SRC.celim2010, SRC.nordlinger2008, SRC.ng151] }),

  tm({ id: "colorectal-peritoneal-metastases", name: "Peritoneal metastases from bowel cancer", category: "Clinical", wikipedia: W("Peritoneal_carcinomatosis"),
    aka: ["colorectal peritoneal metastases", "peritoneal disease in bowel cancer", "cytoreductive surgery and HIPEC for colorectal cancer", "peritoneal carcinomatosis of colorectal origin"],
    tldr: "Bowel cancer can seed the lining of the abdomen rather than travel to the liver or lungs. Where the deposits are confined to that lining and can all be removed, specialist centres offer an operation to strip them out. Adding heated chemotherapy into the abdomen at the end of that operation was tested in a randomised trial and did not help.",
    summary: "What it is and what is offered. Spread across the peritoneum, the membrane lining the abdominal cavity, is a distinct pattern of colorectal metastasis and responds poorly to systemic treatment. NICE NG151 (1.5.21) says that for people whose metastases are limited to the peritoneum, systemic anticancer therapy should be offered and the multidisciplinary team should discuss referral to a nationally commissioned specialist centre to consider cytoreductive surgery with hyperthermic intraperitoneal chemotherapy.\n\nWhat the trial showed. PRODIGE 7 randomised 265 patients at 17 French centres, all of whom had achieved complete macroscopic resection or resection with less than 1 mm of residual tumour, to cytoreductive surgery with or without oxaliplatin hyperthermic intraperitoneal chemotherapy. After a median follow-up of 63.8 months, median overall survival was 41.7 months with the heated chemotherapy and 41.2 months without it (hazard ratio 1.00). Grade 3 or worse adverse events were similar at 30 days but more common in the hyperthermic arm at 60 days (26 against 15 percent). The authors concluded that cytoreductive surgery alone should be the cornerstone of curative-intent treatment (Quenet 2021). The 41-month median survival in both arms is the figure worth carrying: it is the surgery, and the selection of patients fit enough for it with disease complete enough to remove, that produces the outcome.\n\nHow to read a referral. Eligibility in the trial required a Peritoneal Cancer Index of 25 or less, performance status 0 or 1, and fitness for six months of systemic chemotherapy. The general glossary term for peritoneal metastasis covers the same pattern in stomach and other cancers, where the trial evidence is different.",
    cancers: ["colorectal", "colon-cancer", "rectal-cancer", "appendiceal-adenocarcinoma"],
    terms: ["peritoneal-metastasis", "liver-limited-metastatic-colorectal", "conversion-therapy-colorectal"],
    technologies: ["hipec", "ct"],
    links: [SRC.ng151, SRC.quenet2021] }),
];

